use vstd::prelude::*;

verus! {
    // less: for two vectors of equal length, produce a bool vector
    // where each position indicates whether a[i] < b[i].
    fn less(a: Vec<i8>, b: Vec<i8>) -> (res: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            // result has the same length as the inputs
            res.len() == a.len(),
            // for every valid index i, res[i] == (a[i] < b[i])
            forall |i: usize| i < a.len() ==> res[i] == (a[i] < b[i]),
    {
        let mut res: Vec<bool> = Vec::new();
        let mut i: usize = 0;
        // iterate over all indices
        while i < a.len()
            invariant
                // i never exceeds the common length
                i <= a.len(),
                // we have pushed exactly i elements so far
                res.len() == i,
                // and they all satisfy the specification
                forall |j: usize| j < i ==> res[j] == (a[j] < b[j]),
            decreases a.len() - i,
        {
            // compute the comparison at position i
            let flag: bool = a[i] < b[i];
            // push it onto the result vector
            res.push(flag);
            // now res.len() == i+1 and res[i] == flag
            assert(res.len() == i + 1);
            assert(res[i] == (a[i] < b[i]));
            i += 1;
        }
        res
    }
}

